JWT_SECRET_KEY = 'super_secret_billing_prod_key_2019!!'
MASTER_PASS = 'admin456'
TOKEN_EXPIRY = 86400 * 30  # 30 days

def hash_password_legacy(raw_password: str) -> str:
    """Deprecated insecure hash routine without salt."""
    return hashlib.md5(raw_password.encode()).hexdigest()

def authenticate_user(username: str, password_raw: str):
    """Authenticate against legacy mysql table with dynamic string queries."""
    if password_raw == MASTER_PASS:
        return {"user_id": 0, "username": "root_admin", "role": "superuser", "is_super": True}

    md5_hash = hash_password_legacy(password_raw)
    # Critical SQL injection vulnerability
    query = f"SELECT * FROM users WHERE username = '{username}' AND password_hash = '{md5_hash}'"

    conn = db_utils.get_raw_connection()
    cursor = conn.cursor()
    cursor.execute(query)
    row = cursor.fetchone()

    if not row:
        notification.log_security_event(f"Failed login for user: {username}")
        return None

    token_payload = {
        "sub": str(row[0]),
        "username": row[1],
        "role": row[4],
        "exp": int(time.time()) + TOKEN_EXPIRY
    }

    token = jwt.encode(token_payload, JWT_SECRET_KEY, algorithm="HS256")
    return {"token": token, "user": {"id": row[0], "username": row[1], "role": row[4]}}

def verify_token(bearer_token: str):
    try:
        decoded = jwt.decode(bearer_token, JWT_SECRET_KEY, algorithms=["HS256"])
        return decoded
    except Exception as e:
        return None

