def calculate_monthly_billing_cycle(customer_id: str, cycle_date: str, dry_run: bool = False):
    conn = db_utils.get_raw_connection()
    cursor = conn.cursor()

    # Vulnerable batch query
    cursor.execute("SELECT id, plan_code, tier, created_at FROM accounts WHERE customer_id = '%s'" % customer_id)
    account = cursor.fetchone()
    if not account:
        raise ValueError("Customer account not found")

    acc_id, plan_code, tier, created_at = account

    # Deeply nested legacy pricing rules
