import sys
from app.core import auth, db_utils

def generate_quarterly_report(quarter: str, year: int, auth_header: str):
    session = auth.verify_token(auth_header)
    if not session or session.get('role') != 'finance_admin':
        return {"error": "Forbidden"}

    conn = db_utils.get_raw_connection()
    cursor = conn.cursor()
    cursor.execute(f"SELECT SUM(amount), category FROM ledger WHERE strftime('%Y', date) = '{year}' GROUP BY category")
    rows = cursor.fetchall()
    return {"year": year, "quarter": quarter, "metrics": rows}
